 SELECT c.trade_id,to_jsonb(q) AS raw_quote,
        CASE WHEN m.snapshot_time IS NULL THEN NULL ELSE to_jsonb(m)-'omitted' END AS raw_meta
 FROM cohort c JOIN option_chain_snapshots q
 ON q.underlying='NDX' AND q.symbol IN (c.lower_symbol,c.center_symbol,c.upper_symbol)
 AND q.snapshot_time>c.exit_time AND q.snapshot_time<=c.close_time
 LEFT JOIN chain_snapshot_meta m ON m.snapshot_time=q.snapshot_time
 AND m.underlying=q.underlying AND m.expiration=q.expiration
 ORDER BY c.trade_id,q.snapshot_time,q.symbol
) TO STDOUT WITH (FORMAT CSV,HEADER TRUE);
COMMIT;
